CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL CHECK(name IN ('customer','sales_staff','warehouse_staff','designer','admin')), description text NOT NULL DEFAULT '');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone varchar(20) UNIQUE NOT NULL, full_name varchar(120) NOT NULL, password_hash text NOT NULL, role_id uuid NOT NULL REFERENCES roles(id), is_active boolean NOT NULL DEFAULT true, phone_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash char(64) UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX user_sessions_active_idx ON user_sessions(token_hash, expires_at) WHERE revoked_at IS NULL;
CREATE TABLE otp_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone varchar(20) NOT NULL, purpose text NOT NULL CHECK(purpose IN ('register','reset_password')), code_hash char(64) NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, attempts smallint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX otp_phone_purpose_idx ON otp_challenges(phone,purpose,created_at DESC);
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL UNIQUE, description text NOT NULL DEFAULT '', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES categories(id), name varchar(180) NOT NULL, description text NOT NULL DEFAULT '', price_vnd bigint NOT NULL CHECK(price_vnd >= 0), sku varchar(80) UNIQUE NOT NULL, image_url text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE size_charts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES categories(id) ON DELETE CASCADE, name varchar(120) NOT NULL, measurements jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, size varchar(30) NOT NULL, color varchar(50) NOT NULL DEFAULT '', sku varchar(80) UNIQUE NOT NULL, stock_on_hand integer NOT NULL DEFAULT 0 CHECK(stock_on_hand >= 0), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,size,color));
CREATE TABLE inventory_adjustments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variant_id uuid NOT NULL REFERENCES product_variants(id), changed_by uuid NOT NULL REFERENCES users(id), delta integer NOT NULL CHECK(delta <> 0), quantity_before integer NOT NULL, quantity_after integer NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inventory_history_idx ON inventory_adjustments(variant_id,created_at DESC);
CREATE TABLE wishlists (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id));
